      "coreTheory": "1. **정형 데이터 (Structured Data)**:\n   - 고정된 행(Row)과 열(Column)의 테이블 스키마 구조를 가짐.\n   - 관계형 데이터베이스(RDB), 스프레드시트(Excel), CSV 등.\n   - 연산과 정렬, 통계 처리가 가장 용이함.\n2. **반정형 데이터 (Semi-structured Data)**:\n   - 고정된 테이블 스키마는 없으나, 데이터의 내용과 구조를 설명하는 메타데이터나 태그(Tag)를 포함함.\n   - HTML, XML, JSON, 웹 서버 로그(Access Log), 센서 데이터 등.\n   - 파싱(Parsing) 과정을 거쳐 구조화된 데이터로 변환 가능.\n3. **비정형 데이터 (Unstructured Data)**:\n   - 연산이나 형태 정의가 불가능한 순수한 데이터.\n   - 텍스트 문서(Word, PDF), 소셜 미디어 게시글, 이미지, 음성, 동영상 등.\n   - 빅데이터의 약 80% 이상을 차지하며 텍스트 마이닝이나 딥러닝 기법으로 분석함.",
