      "coreTheory": "1. **통합된 데이터 (Integrated Data)**:\n   - 동일한 데이터의 중복(Redundancy)을 최소화(배제)하여 데이터 불일치와 무결성 훼손을 방지함.\n2. **저장된 데이터 (Stored Data)**:\n   - 컴퓨터 시스템이 직접 접근하여 읽고 쓸 수 있는 디지털 저장 매체(자기디스크, SSD 등)에 영구 보관됨.\n3. **운영 데이터 (Operational Data)**:\n   - 단순 참고용이 아니라, 조직의 고유 업무를 정상적으로 수행하기 위해 없어서는 안 될 필수 불가결한 데이터.\n4. **공용 데이터 (Shared Data)**:\n   - 특정 1인이 독점하는 것이 아니라, 여러 응용 시스템과 다양한 부서의 다수 사용자가 동시에 공동으로 활용함.",
