      "oneLiner": "OLTP(실시간 일상 업무 트랜잭션 입력/수정/삭제) vs OLAP(다차원 의사결정 지원 분석 및 회전)",
      "coreTheory": "1. **OLTP (Online Transaction Processing)**:\n   - 은행 계좌 이체, 쇼핑몰 주문 결제 등 실시간 데이터의 빈번한 입력(Insert), 수정(Update), 삭제(Delete)를 지원하는 일상 업무 지원 시스템.\n   - 데이터의 무결성과 트랜잭션의 ACID(원자성, 일관성, 고립성, 지속성) 보장이 생명.\n2. **OLAP (Online Analytical Processing)**:\n   - 데이터웨어하우스(DW)에 축적된 방대한 이력 데이터를 다차원(Multi-dimensional) 큐브 형태로 구성하여 경영진의 의사결정을 지원하는 분석 시스템.\n   - **4대 핵심 연산 기능**:\n     - **Roll-up**: 요약 수준을 높여 더 넓은 관점으로 집계 (일별 → 월별 → 연도별).\n     - **Drill-down**: 반대로 상세 수준으로 파고들어 세부 데이터 확인 (연도별 → 분기별 → 일별).\n     - **Slicing**: 다차원 큐브에서 특정 1개 차원을 자른 단면 보기.\n     - **Dicing**: 작은 주사위 큐브 형태로 여러 차원의 하위 부분집합 추출.",
      "metaphor": "편의점 계산대 바코드 스캐너(OLTP: 1초마다 결제 처리) vs 본사 임원실의 대형 매출 대시보드(OLAP: 전국 매출을 연령별/지역별/월별로 이리저리 돌려보며 분석).",
      "analogy": "편의점 계산대 바코드 스캐너(OLTP: 1초마다 결제 처리) vs 본사 임원실의 대형 매출 대시보드(OLAP: 전국 매출을 연령별/지역별/월별로 이리저리 돌려보며 분석).",
      "trapsAndTips": "- 🚨 **단골 함정**: OLAP 시스템은 실시간 데이터 수정과 삭제가 주된 목적이다? → 100% 오답! 수정/삭제는 OLTP이며, OLAP은 읽기 위주의 다차원 분석입니다.\n- 📌 **1초 암기 공식**: 일상 트랜잭션=OLTP, 다차원 분석 큐브=OLAP (Roll-up, Drill-down, Slicing, Dicing)!",
