      "coreTheory": "1. **데이터웨어하우스 (DW, Data Warehouse)**:\n   - 기업 내 여러 이종 시스템(ERP, CRM, 레거시 등)의 데이터를 전사적으로 한곳에 통합·정제하여 분석용으로 구축한 중앙 저장소.\n   - **DW의 4대 고유 특성**:\n     - ① **주제 지향성 (Subject-Oriented)**: 일상 업무 처리가 아니라 고객, 제품, 매출 등 특정 '주제' 중심으로 데이터가 조직화됨.\n     - ② **데이터 통합성 (Integrated)**: 서로 다른 소스 시스템의 데이터 형식, 코드, 단위(예: 성별 M/F vs 1/2)를 하나로 통일함.\n     - ③ **시계열성 (Time-Variant)**: 5년, 10년 등 과거부터 현재까지의 시간 흐름에 따른 이력 데이터를 보존함.\n     - ④ **비휘발성 (Non-Volatile)**: 한 번 적재되면 데이터의 수정이나 삭제가 발생하지 않는 읽기 전용(Read-Only) 특성.\n2. **데이터마트 (DM, Data Mart)**:\n   - 전사 DW가 너무 방대하므로, 마케팅팀, 재무팀 등 특정 부서나 특정 목적에 특화하여 DW에서 추출해 구축한 소규모 맞춤형 데이터베이스.",
