      "coreTheory": "1. **사생활 침해 (Privacy)**:\n   - 데이터가 무한 재조합되어 개인의 사생활이 노출됨.\n   - 통제 방안: 개인의 사전 동의(Opt-in) 제도의 한계를 인정하고, 데이터를 실제로 활용하여 이익을 얻는 **'데이터 사용자 책임제'**로 패러다임 전환.\n2. **책임 원칙 훼손 (Responsibility)**:\n   - 범죄 예측 알고리즘 등에 의해 아직 행동을 저지르기도 전에 잠재적 성향만으로 불이익을 당함 (마이너리티 리포트).\n   - 통제 방안: 예측된 성향이 아니라 실제 저지른 행위에 대해서만 책임을 묻는 **'결과 기반 책임 원칙'** 준수.\n3. **데이터 오용 (Data Abuse)**:\n   - 잘못된 통계와 가짜 상관관계를 맹신하여 부당한 의사결정을 내림.\n   - 통제 방안: 알고리즘의 편향과 데이터 해석의 타당성을 감시하고 객관적으로 평가하는 전문 인력인 **'알고리즈미스트(Algorithmist)'** 도입.",
