      "coreTheory": "1. **Optimization (최적화)**:\n   - 대상(What) 알고, 방법(How)도 앎.\n   - 기존의 업무 프로세스를 개선하여 운영 효율성과 성과를 극대화하는 방식.\n2. **Solution (솔루션)**:\n   - 대상(What)은 알지만, 구체적 분석 방법(How)을 모름.\n   - 당면한 과제를 해결하기 위해 새로운 분석 기법이나 알고리즘, 외부 솔루션을 도입함.\n3. **Insight (통찰)**:\n   - 분석 대상(What)은 특정하지 못했으나, 보유한 분석 기술과 역량(How)은 있음.\n   - 기존 데이터를 다각도로 탐색하여 생각지 못했던 새로운 통찰과 기회를 발굴함.\n4. **Discovery (발견)**:\n   - 대상(What)도 모르고, 방법(How)도 모름.\n   - 백지 상태에서 완전히 새로운 비즈니스 영역을 개척하기 위해 전면적으로 과제를 탐색함.",
