      "coreTheory": "조직의 분석 역량이 얼마나 성숙했는지를 CMMI 모델을 준용하여 4단계로 측정합니다.\n1. **1단계: 도입 (Introduction)**:\n   - 데이터 분석을 시작하는 단계로, 비즈니스 현황을 파악하고 기초적인 분석 환경을 모색함.\n2. **2단계: 활용 (Utilization)**:\n   - 일부 실무 부서를 중심으로 분석 기법을 업무에 적용하여 가시적인 비즈니스 성과를 창출함.\n3. **3단계: 확산 (Expansion)**:\n   - 전사적 분석 시스템이 구축되고, 부서 간 분석 결과와 모범 사례(Best Practice)가 공유됨.\n4. **4단계: 최적화 (Optimization)**:\n   - 실시간 빅데이터 분석과 예측 알고리즘이 경영진의 일상적인 의사결정과 제품/서비스 혁신에 완전히 내재화된 최상위 단계.",
