      "coreTheory": "1. **집중형 (Centralized Structure)**:\n   - 전사 분석 전담 부서가 중앙에서 모든 사업부의 분석 과제를 일괄 총괄 수행.\n   - 장점: 전사적 분석 표준화, 중복 투자 방지, 우선순위 통제 우수.\n   - 단점: 현업 실무 부서와의 소통 부족, 현장 밀착감 저하, 현업의 분석 요청 적체.\n2. **기능형 (Functional Structure)**:\n   - 별도의 전담 분석 부서 없이, 마케팅, 재무, 영업 등 각 사업 부서 내부에서 자체적으로 분석 인력을 두고 수행.\n   - 장점: 현업 실무 밀착도 극대화, 빠른 실무 적용.\n   - 단점: 전사적 시너지 창출 불가, 부서 간 중복 투자 및 분석 표준화 실패.\n3. **분산형 (Decentralized Structure)**:\n   - 전사 분석 전담 조직이 존재하면서, 소속 분석가들을 각 사업 부서에 직접 배치/파견하여 협력함.\n   - 장점: 현업 친화력과 전사적 거버넌스를 동시에 확보.\n   - 단점: 분석 인력의 이중 소속감 및 과제 우선순위 갈등 발생 가능.",
