      "coreTheory": "CRISP-DM은 전 세계 데이터 마이닝 실무에서 가장 널리 쓰이는 표준 프로세스 모델입니다.\n1. **① 업무 이해 (Business Understanding)**:\n   - 비즈니스 목표와 요구사항 파악, 분석 목적을 데이터 마이닝 문제로 변환, 프로젝트 계획 수립.\n2. **② 데이터 이해 (Data Understanding)**:\n   - 초기 데이터 수집, 데이터 속성 파악, 데이터 품질 확인, 탐색적 데이터 분석(EDA).\n3. **③ 데이터 준비 (Data Preparation)**:\n   - 모델링에 입력할 수 있도록 데이터를 정제하고 변환함 (결측치 처리, 파생변수 생성, 데이터셋 편성).\n4. **④ 모델링 (Modeling)**:\n   - 다양한 머신러닝/통계 기법을 적용하고 하이퍼파라미터를 최적 튜닝함.\n5. **⑤ 평가 (Evaluation)**:\n   - 모델의 성능 지표뿐만 아니라, 최초의 비즈니스 목표를 실제로 달성했는지 최종 평가함.\n6. **⑥ 전개 (Deployment)**:\n   - 완성된 모델을 현업 운영 시스템에 배포하고 유지보수 계획을 수립함.",
