      "coreTheory": "1. **KDD 5단계 프로세스 (Knowledge Discovery in Databases)**:\n   - ① **데이터 선택 (Selection)**: 비즈니스 도메인 이해를 바탕으로 분석에 필요한 목표 데이터셋(Target Data)을 추출함.\n   - ② **데이터 전처리 (Preprocessing)**: 잡음(Noise)과 이상치를 제거하고 결측치를 처리하여 정제된 데이터(Cleaned Data)를 생성함.\n   - ③ **데이터 변환 (Transformation)**: 차원 축소, 파생변수 생성, 정규화 등을 통해 마이닝에 적합한 형태의 변환된 데이터(Transformed Data)를 만듦.\n   - ④ **데이터 마이닝 (Data Mining)**: 패턴을 찾기 위해 분류, 군집, 연관 등 데이터 마이닝 알고리즘을 적용함.\n   - ⑤ **해석 및 평가 (Interpretation/Evaluation)**: 마이닝 결과를 해석하고 지식(Knowledge)을 도출함.\n2. **CRISP-DM과의 매핑 비교**:\n   - KDD의 '데이터 선택 + 전처리 + 변환' 3단계가 CRISP-DM의 **'데이터 준비(Data Preparation)'** 단계에 해당함.",
