      "coreTheory": "1. **R 언어의 특징**:\n   - 통계 및 데이터 시각화에 특화된 오픈소스 언어이자 객체지향 인터프리터 언어.\n   - **대소문자를 엄격하게 구분**함 (`a`와 `A`는 서로 다른 변수).\n   - 인덱스가 **1부터 시작**함 (Python/C는 0부터 시작하므로 주의).\n\n2. **할당 연산자 (Assignment)**:\n   - `<-` (권장 표준) 또는 `=` 사용: `x <- 10`\n   - 전역 할당: `<<-` (함수 내부에서 상위 환경이나 전역 변수 수정 시 사용).\n\n3. **산술 및 특수 연산자**:\n   - `+`, `-`, `*`, `/`: 기본 사칙연산\n   - `^` 또는 `**`: 거듭제곱 (예: `2^3 = 8`)\n   - `%%`: **나머지 연산자** (예: `7 %% 3 = 1`)\n   - `%/%`: **정수 몫 연산자** (예: `7 %/% 3 = 2`)\n   - `%*%`: **행렬의 곱셈** (Matrix Multiplication)\n\n4. **비교 및 논리 연산자**:\n   - `==`, `!=`, `<`, `>`, `<=`, `>=`: 비교 연산자 (결과는 TRUE/FALSE)\n   - `&`, `|`, `!`: 벡터 원소별(element-wise) AND, OR, NOT 연산\n   - `&&`, `||`: 첫 번째 원소만 비교하는 스칼라 논리 연산",
