      "coreTheory": "1. **데이터 재구조화의 필요성**:\n   - 통계 분석 및 시각화(ggplot2 등)에서는 열이 옆으로 넓게 퍼진 'Wide 형태'보다 관측치가 아래로 길게 나열된 **'Long 형태 (Tidy Data)'**가 훨씬 유리합니다.\n\n2. **`melt()` 함수 (Wide → Long)**:\n   - 가로로 넓게 나열된 여러 측정치 열을 녹여서 **식별자(id.vars), 측정 변수명(variable), 값(value)**의 3개 컬럼 중심 긴 형태로 변환.\n   - 예: `melt(data, id.vars = c(\"ID\", \"Name\"))`\n\n3. **`dcast()` & `acast()` 함수 (Long → Wide)**:\n   - 녹여진 Long 데이터를 새로운 행과 열 구조로 요약 및 재배치(Casting).\n   - **`dcast()`**: 결과를 **데이터프레임(Data Frame)**으로 반환 (`d` = data.frame).\n   - **`acast()`**: 결과를 **배열(Array)이나 행렬(Matrix)**로 반환 (`a` = array).\n   - 문법 형태: `dcast(data, 행_기준_변수 ~ 열_기준_변수, 집계함수)`",
