        "explanation": "1) IQR = Q3 - Q1 = 80 - 40 = 40. 2) 1.5 × IQR = 1.5 × 40 = 60. 3) 하한선 = Q1 - 60 = 40 - 60 = -20점 미만. 4) 상한선 = Q3 + 60 = 80 + 60 = 140점 초과. 따라서 정답은 3번입니다."
