      "coreTheory": "서로 다른 단위(예: 연봉 5,000만원 vs 나이 30세)를 가진 변수들의 스케일을 맞춰 머신러닝 거리 계산 왜곡을 막는 기법입니다.\n\n| 구분 | **최소-최대 정규화 (Min-Max Normalization)** | **Z-점수 표준화 (Standardization / Z-Score)** |\n| :--- | :--- | :--- |\n| **공식** | $X_{new} = \\frac{X - X_{min}}{X_{max} - X_{min}}$ | $Z = \\frac{X - \\mu}{\\sigma}$ |\n| **변환 후 범위** | **무조건 0과 1 사이 ($[0, 1]$)** | 특정 상하한 없음 (보통 -3 ~ +3에 99.7% 분포) |\n| **중심값** | 0.5 부근 | **평균 = 0, 표준편차 = 1** |\n| **이상치 민감도** | **극도로 취약** (이상치 하나가 전체 0~1 분포를 압축 왜곡함) | 상대적으로 강건 (이상치가 있어도 평균/표준편차 기반 완충) |\n| **R 함수** | 사용자 정의 함수 생성 필요 | `scale(x)` 기본 내장 함수 |",
      "metaphor": "정규화는 학생들의 성적을 100점 만점으로 전부 환산해 0~100점 통에 욱여넣는 것이고, 표준화는 반 평균을 딱 0점에 맞추고 평균보다 1표준편차 잘했으면 +1점, 못했으면 -1점으로 표시하는 상대평가 성적표입니다.",
