      "coreTheory": "1. **평균 3총사와 활용 분야**:\n   - **산술평균 (Arithmetic Mean)**: 모든 값을 더해 개수로 나눈 값. 이상치에 극도로 취약.\n   - **기하평균 (Geometric Mean)**: 값들을 모두 곱한 후 n제곱근. **연평균 경제성장률, 물가상승률, 수익률** 등 비율 변화율 계산에 사용.\n   - **조화평균 (Harmonic Mean)**: 역수의 산술평균의 역수. **평균 속력, 시급 등 단위당 비율** 계산에 사용.\n   - **★대소 관계**: 모든 양수 데이터에 대해 항상 **산술평균 ≥ 기하평균 ≥ 조화평균** 성립.\n\n2. **중앙값 (Median)**:\n   - 자료를 크기순으로 세웠을 때 정중앙에 위치하는 값.\n   - 데이터 개수 $n$이 홀수면 $\\frac{n+1}{2}$번째 값, 짝수면 가운데 두 값의 평균.\n   - **이상치(극단값)에 영향을 받지 않는 가장 대표적인 저항성(Robust) 통계량**.\n\n3. **최빈값 (Mode)**:\n   - 빈도수가 가장 많은 값. 명목형/범주형 데이터에서도 유일하게 사용 가능한 대표값.",
