      "coreTheory": "연속적인 측정값을 다루며, 각종 통계 검정의 가설 검증 통계량으로 사용되는 핵심 분포들입니다.\n\n| 분포명 | 핵심 특징 및 용도 | 주요 성질 및 형태 |\n| :--- | :--- | :--- |\n| **정규분포 ($N(\\mu, \\sigma^2)$)** | 자연계와 사회현상에서 가장 보편적인 대칭 분포 | 평균 $\\mu$와 분산 $\\sigma^2$에 의해 결정되는 종 모양 곡선 |\n| **표준정규분포 ($Z$)** | $Z = \\frac{X - \\mu}{\\sigma}$로 변환한 표준화 분포 | **평균 = 0, 분산 = 1**인 $N(0, 1)$ |\n| **t-분포 (Student's t)** | **모분산을 모를 때, 표본 크기($n < 30$)가 작은 경우 모평균 검정**에 사용 | 0 중심 대칭이나 정규분포보다 꼬리가 두꺼움. **자유도가 커질수록 표준정규분포에 수렴** |\n| **카이제곱 분포 ($\\chi^2$)** | **모분산 검정, 적합도 검정, 분할표의 독립성/동질성 검정**에 사용 | 표준정규변수들의 제곱합으로 정의. **항상 0 이상의 양수값만 가짐 (오른쪽 긴 꼬리)** |\n| **F-분포** | **두 집단의 분산 동일성 검정, 회귀분석 유의성 검정, 분산분석(ANOVA)**에 사용 | **두 개의 독립적인 카이제곱 변수의 비(Ratio)**로 정의. 항상 0 이상의 양수값 |",
