      "coreTheory": "1. **중심극한정리 (CLT: Central Limit Theorem)의 정의**:\n   - 모집단의 분포가 정규분포가 아니더라도(균등분포, 지수분포 등 어떤 형태든),\n   - **표본의 크기 $n$이 충분히 크다면 (통상적으로 $n \\ge 30$)**,\n   - 표본평균($\\bar{X}$)들의 확률분포는 모평균 $\\mu$와 분산 $\\frac{\\sigma^2}{n}$을 따르는 **정규분포 $N(\\mu, \\frac{\\sigma^2}{n})$에 근사**한다는 정리.\n\n2. **핵심 포인트**:\n   - 표본평균의 평균은 모평균과 일치: $E(\\bar{X}) = \\mu$\n   - 표본평균의 표준편차(**표준오차 Standard Error**)는 표본 크기 $n$이 커질수록 $\\sqrt{n}$에 반비례하여 감소: $SE = \\frac{\\sigma}{\\sqrt{n}}$\n   - 현대 통계적 추정과 가설검정의 가장 핵심적인 수학적 근거가 됨.",
