      "coreTheory": "1. **귀무가설 ($H_0$, Null Hypothesis)**:\n   - '돌아갈 귀(歸), 없을 무(無)' → \"아무런 차이가 없다, 효과가 없다, 기존 통념과 같다.\"\n   - 연구자가 **기각(Reject)되기를 바라는 가설**.\n   - 기각할 만한 강력한 반증 증거가 수집되지 않으면 무죄추정의 원칙처럼 일단 참으로 유지됨.\n\n2. **대립가설 ($H_1$ 또는 $H_a$, Alternative Hypothesis)**:\n   - 귀무가설과 대립되는 가설로, **\"차이가 있다, 신약의 효과가 있다, 변화가 생겼다.\"**\n   - 연구자가 **데이터를 통해 새롭게 증명하고 주장하고 싶어 하는 핵심 가설**.\n\n3. **양측검정 vs 단측검정**:\n   - **양측검정 (Two-sided)**: $H_0: \\mu = \\mu_0$ vs $H_1: \\mu \\ne \\mu_0$ (차이가 있는지만 볼 때).\n   - **단측검정 (One-sided)**: $H_1: \\mu > \\mu_0$ (크다) 또는 $H_1: \\mu < \\mu_0$ (작다) (방향성이 있을 때).",
