      "coreTheory": "1. **p-value (Probability Value, 유의확률)의 통계적 정의**:\n   - **귀무가설($H_0$)이 참이라는 가정하에**, 현재 관측된 표본 데이터(또는 그보다 더 극단적인 데이터)가 우연히 나타날 확률.\n\n2. **★가설 기각 판정 황금률 (암기 필수)**:\n   - **$p < \\alpha$ ($p < 0.05$)**:\n     - \"우연히 일어날 확률이 5%도 안 될 정도로 극히 희박하다!\"\n     - $\\rightarrow$ **귀무가설($H_0$) 기각, 대립가설($H_1$) 채택**!\n     - 결론: \"통계적으로 유의미한 차이가 있다 (Statistically Significant).\"\n   - **$p \\ge \\alpha$ ($p \\ge 0.05$)**:\n     - \"우연히 얼마든지 일어날 수 있는 평범한 현상이다.\"\n     - $\\rightarrow$ **귀무가설($H_0$) 기각 실패 (채택)**.\n     - 결론: \"통계적으로 유의미한 차이가 있다고 볼 수 없다.\"",
