      "analogy": "동전을 100번 던졌는데 100번 다 앞면이 나왔습니다. '이 동전이 정상(귀무가설)'일 때 이런 일이 일어날 확률(p-value)은 0.000000001%입니다. 그러니 우리는 '이 동전은 사기다(귀무가설 기각)'라고 결론 내립니다.",
