      "oneLiner": "피어슨(연속형 등간/비율 척도, 선형관계 강도) vs 스피어만(서열/순위 척도, 비선형 단조관계, 비모수)",
      "coreTheory": "두 변수 간의 연관성(상관관계)의 방향과 강도를 측정하는 분석 기법입니다.\n\n| 구분 | **피어슨 상관계수 ($r$)** | **스피어만 상관계수 ($\\rho$)** |\n| :--- | :--- | :--- |\n| **데이터 유형** | **연속형 변수 (등간척도, 비율척도)** | **순서형/서열 변수 (서열척도) 또는 비정규 연속형** |\n| **모수/비모수** | **모수적 기법 (정규분포 가정 필수)** | **비모수적 기법 (분포 무관)** |\n| **측정 대상** | 두 변수 사이의 **'선형적(Linear)' 관계** | 두 변수 사이의 **'단조적(Monotonic)' 증가/감소 관계** |\n| **계산 원리** | 공분산을 각 변수의 표준편차 곱으로 나눔 | 원데이터를 **순위(Rank)**로 변환한 후 피어슨 공식 적용 |\n| **이상치 영향** | **이상치에 매우 민감하게 왜곡됨** | 순위 기반이므로 **이상치에 매우 강건(Robust)** |\n\n- **상관계수 범위**: $-1 \\le r \\le +1$\n  - $+1$: 완벽한 양의 선형상관, $-1$: 완벽한 음의 선형상관, $0$: 선형상관 관계 없음.",
      "metaphor": "피어슨은 두 학생의 시험 점수 원점수(85점, 92점)로 키와 몸무게의 정밀한 비례 관계를 재는 것이고, 스피어만은 전교 등수(1등, 2등, 3등)만 가지고 순위가 같이 오르는지 내리는지 따지는 비모수 심판입니다.",
      "analogy": "피어슨은 두 학생의 시험 점수 원점수(85점, 92점)로 키와 몸무게의 정밀한 비례 관계를 재는 것이고, 스피어만은 전교 등수(1등, 2등, 3등)만 가지고 순위가 같이 오르는지 내리는지 따지는 비모수 심판입니다.",
