      "coreTheory": "1. **카이제곱 통계량 ($\\chi^2$) 공식**:\n   $$\\chi^2 = \\sum \\frac{(O - E)^2}{E} \\quad (O: \\text{관측빈도}, E: \\text{기대빈도})$$\n   - 관측된 빈도가 이론적 기대빈도와 차이가 클수록 $\\chi^2$ 값이 커져서 귀무가설이 기각됨.\n\n2. **카이제곱 검정의 3가지 유형**:\n   - **적합도 검정 (Goodness-of-Fit)**:\n     - 1개의 범주형 변수가 특정 이론적 확률분포(예: 멘델 유전법칙 9:3:3:1)를 따르는지 검정. (자유도 = $k - 1$).\n   - **독립성 검정 (Test of Independence)**:\n     - 2개의 범주형 변수가 서로 독립인지 연관되어 있는지 검정 (예: 성별과 선호 정당 간 연관성).\n   - **동질성 검정 (Test of Homogeneity)**:\n     - 여러 모집단(그룹)에서 특정 범주형 변수의 비율이 서로 동일한지 검정 (예: 20대, 30대, 40대 집단별 스마트폰 브랜드 선호 비율).\n\n3. **★교차분할표의 자유도 (시험 단골 계산)**:\n   - 행의 수가 $r$, 열의 수가 $c$인 $r \\times c$ 분할표의 자유도: **$(r - 1)(c - 1)$**",
