      "oneLiner": "독립변수 X 하나로 종속변수 Y를 예측! 잔차제곱합(SSE)을 최소화하는 최적의 직선(Y = β0 + β1X)",
      "coreTheory": "1. **단순선형회귀 모형의 형태**:\n   $$Y_i = \\beta_0 + \\beta_1 X_i + \\epsilon_i$$\n   - $Y$: 종속변수 (반응변수, 결과)\n   - $X$: 독립변수 (설명변수, 원인)\n   - $\\beta_0$: 절편 (Intercept, $X=0$일 때의 $Y$값)\n   - $\\beta_1$: 기울기 (Slope, **$X$가 1단위 증가할 때 $Y$의 평균 변화량**)\n   - $\\epsilon_i$: 오차항 (Error term)\n\n2. **★최소제곱법 (OLS: Ordinary Least Squares)**:\n   - 실제 관측값 $Y_i$와 회귀선에 의한 예측값 $\\hat{Y}_i$의 차이인 **잔차(Residual)의 제곱들의 합(SSE)을 최소화**하도록 회귀계수 $\\beta_0$와 $\\beta_1$을 추정하는 수학적 방법:\n     $$\\min \\sum e_i^2 = \\sum (Y_i - \\hat{Y}_i)^2$$\n\n3. **회귀직선의 핵심 성질**:\n   - 잔차들의 단순 합은 항상 0이다: $\\sum e_i = 0$\n   - 회귀선은 항상 독립변수와 종속변수의 평균점인 $(\\bar{X}, \\bar{Y})$를 반드시 통과한다!",
      "metaphor": "산포도에 흩뿌려진 수많은 점들 사이로 실을 팽팽하게 당길 때, 각 점들에서 실까지 수직 거리(잔차)를 재서 그 거리 제곱들의 합이 가장 작아지도록 놓는 '가장 공평한 기준 직선'을 찾는 방법입니다.",
