      "coreTheory": "1. **총 제곱합의 분해 (SST = SSR + SSE)**:\n   - **SST (총제곱합, Total)**: $\\sum (Y_i - \\bar{Y})^2$, 종속변수 $Y$의 전체 변동. (자유도: $n - 1$)\n   - **SSR (회귀제곱합, Regression)**: $\\sum (\\hat{Y}_i - \\bar{Y})^2$, 회귀직선에 의해 **설명되는 변동**. (자유도: 설명변수 개수 $k$)\n   - **SSE (잔차제곱합, Error)**: $\\sum (Y_i - \\hat{Y}_i)^2$, 회귀선으로 **설명되지 못하는 오차 변동**. (자유도: $n - k - 1$)\n\n2. **★회귀모형의 통계적 유의성 검정 (F-검정)**:\n   - **귀무가설 ($H_0$)**: $\\beta_1 = \\beta_2 = \\dots = \\beta_k = 0$ (모든 회귀계수가 0이다, 즉 모형이 쓸모없다).\n   - **대립가설 ($H_1$)**: 적어도 하나의 $\\beta_j \\ne 0$ (유의미한 설명변수가 최소 하나는 있다).\n   - **F 검정통계량**:\n     $$F = \\frac{MSR}{MSE} = \\frac{SSR / k}{SSE / (n - k - 1)}$$\n   - $F$의 $p < 0.05$이면 회귀모형 전체가 통계적으로 매우 유의미하다고 판정!",
