      "coreTheory": "1. **결정계수 ($R^2$, Coefficient of Determination)**:\n   - 종속변수 $Y$의 전체 변동 중 회귀모형이 설명해내는 변동의 비율:\n     $$R^2 = \\frac{SSR}{SST} = 1 - \\frac{SSE}{SST}$$\n   - **범위**: $0 \\le R^2 \\le 1$ ($1$에 가까울수록 설명력이 높고 완벽한 모형).\n   - 단순선형회귀에서는 피어슨 상관계수 $r$의 제곱과 정확히 일치 ($R^2 = r^2$).\n\n2. **★수정 결정계수 (Adjusted $R^2$, $R_{adj}^2$) - 시험 단골**:\n   - **결정계수 $R^2$의 치명적 한계**: 유의미하지 않은 무의미한 독립변수를 억지로 추가하기만 해도 $R^2$ 값은 무조건 증가함!\n   - **수정 결정계수의 해결책**: 표본 크기($n$)와 독립변수 개수($k$)의 자유도를 반영하여, **유의하지 않은 변수를 추가하면 오히려 값이 감소하도록 페널티(벌칙)**를 부여함!\n   - 따라서 **다중회귀분석에서 모형 간의 설명력을 비교할 때는 반드시 $R^2$가 아닌 수정 $R^2$를 기준**으로 삼아야 함!\n   - (항상 $R_{adj}^2 \\le R^2$ 성립).",
