      "coreTheory": "회귀모형의 최소제곱추정량(OLS)이 최적의 선형불편추정량(BLUE)이 되기 위해 반드시 만족해야 하는 4대 가정입니다.\n\n| 기본 가정 | 내용 및 통계적 의미 | 진단 및 검정 방법 |\n| :--- | :--- | :--- |\n| **1. 선형성 (Linearity)** | 독립변수 $X$와 종속변수 $Y$ 사이에 선형(직선) 관계가 존재해야 함 | 산점도(Scatter Plot), 잔차 산점도 |\n| **2. 등분산성 (Homoscedasticity)** | 독립변수 값의 크기와 상관없이 오차(잔차)의 **분산이 항상 일정**해야 함 | 잔차도(Residual Plot)에서 부채꼴/나팔꽃 패턴이 없어야 함 |\n| **3. 독립성 (Independence)** | 잔차들끼리 서로 상관관계(자기상관)가 없어야 함 | **더빈-왓슨 검정 (Durbin-Watson test)** *(시계열 데이터에서 특히 중요)* |\n| **4. 정규성 (Normality)** | 오차(잔차)의 분포가 평균이 0이고 분산이 $\\sigma^2$인 **정규분포**를 따라야 함 | **Q-Q Plot (직선상에 점 일치)**, 샤피로-윌크 검정 (Shapiro-Wilk) |",
      "metaphor": "네 다리가 모두 똑같은 길이여야 안정적인 4각 식탁처럼, 선형성·등분산성·독립성·정규성이라는 4개 기둥 중 하나라도 무너지면 회귀분석 예측치는 와르르 흔들리고 맙니다.",
