      "coreTheory": "1. **다중공선성 (Multicollinearity)의 정의와 증상**:\n   - 모형 안의 독립변수들끼리 강한 선형상관관계가 존재할 때 발생.\n   - **이상 증상 (시험 단골)**:\n     - 회귀모형 전체의 F검정은 유의한데 ($p < 0.05$), 개별 독립변수들의 t검정은 대부분 유의하지 않게 나옴 ($p > 0.05$).\n     - 회귀계수의 부호가 상식과 정반대로 뒤집히거나 분산이 과도하게 팽창함.\n\n2. **★분산팽창요인 (VIF: Variance Inflation Factor)**:\n   - $VIF_i = \\frac{1}{1 - R_i^2}$ ($R_i^2$는 $i$번째 변수를 나머지 독립변수들로 회귀했을 때의 설명력).\n   - 판정 기준: **$VIF \\ge 10$ (보수적으로는 4 또는 5 이상)이면 심각한 다중공선성이 존재**한다고 판정!\n\n3. **다중공선성 해결 방안**:\n   - 상관관계가 높은 변수 중 중요도가 낮은 변수를 모형에서 제거(Drop).\n   - 능형회귀(Ridge) 또는 라쏘(Lasso) 규제 적용.\n   - 주성분분석(PCA)을 통해 독립적인 소수의 주성분 변수로 차원 축소.",
