      "examTrap": "★3대 조건 낚시: 공분산 조건에서 '공분산은 시점 t에 의존한다'고 나오면 100% 오답입니다! 시점 $t$에는 절대 의존하지 않고 오직 **'시차(간격 $k$)'**에만 의존합니다.",
