      "coreTheory": "대부분의 현실 시계열 데이터(주가, 매출액 등)는 비정상 시계열입니다. 이를 정상 시계열로 바꾸는 2대 변환법입니다.\n\n| 데이터의 이상 증상 | 정상화 변환 해법 | 구체적 계산 방법 |\n| :--- | :--- | :--- |\n| **평균이 일정하지 않은 경우**<br>*(우상향/우하향 추세 Trend 존재)* | **차분 (Differencing)** | 현시점 데이터에서 바로 이전 시점 데이터를 뺌:<br>$\\nabla X_t = X_t - X_{t-1}$ (일반 차분)<br>계절성이 있으면 계절 주기 $s$만큼 뺌:<br>$\\nabla_s X_t = X_t - X_{t-s}$ (계절 차분) |\n| **분산이 일정하지 않은 경우**<br>*(시간이 갈수록 진폭/변동폭 확대)* | **로그 변환 (Log Transform)**<br>또는 제곱근 변환 | $Y_t = \\ln(X_t)$<br>값들의 상대적 변동폭을 압축하여 분산을 일정하게 안정화 |\n| **평균과 분산 둘 다 불안정한 경우** | **로그 변환 후 차분 수행** | 1단계로 로그 변환하여 분산 안정화 $\\rightarrow$ 2단계로 차분하여 평균 안정화 |",
      "metaphor": "오르막길(추세)을 걷고 있을 때는 앞걸음과 뒷걸음의 차이(차분)만 보면 평지가 되고, 소리(분산)가 점점 너무 커져 귀가 찢어질 것 같을 때는 볼륨 압축기(로그 변환)를 씌워 소리 크기를 일정하게 맞추는 원리입니다.",
      "analogy": "오르막길(추세)을 걷고 있을 때는 앞걸음과 뒷걸음의 차이(차분)만 보면 평지가 되고, 소리(분산)가 점점 너무 커져 귀가 찢어질 것 같을 때는 볼륨 압축기(로그 변환)를 씌워 소리 크기를 일정하게 맞추는 원리입니다.",
      "trapsAndTips": "★초단골 짝짓기 문제: '평균이 일정하지 않을 때 분산을 변환하기 위해 차분을 쓴다'처럼 평균과 분산의 짝을 바꿔놓습니다. **평균 안정화 = 차분, 분산 안정화 = 로그 변환**! 절대 헷갈리지 마세요.",
