        "explanation": "재현율(Recall, 민감도) = TP / (TP + FN) = 80 / (80 + 20) = 80 / 100 = 0.80(80%)입니다. (참고로 정밀도는 TP / (TP + FP) = 80 / (80 + 10) = 88.9%입니다)."
